<?php
namespace App\Domain\CaseStudies; use Illuminate\Support\Facades\Cache; use Throwable; final class CaseStudyCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.case-studies.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.case-studies.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.case-studies.version.$id",hrtime(true));Cache::put('public.case-studies.index.version',hrtime(true));}catch(Throwable){}} }
